import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring } from "remotion";

/**
 * Scene2 Animation Component
 * Generated by Motion Animation Stage (Custom Code Mode)
 * Implements scene-specific animation with Remotion core primitives.
 */
export const Scene2: React.FC<{ layer?: any }> = () => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durFrames = Math.max(1, Math.round(4.33 * fps));

  // Entrance animations
  const titleSpring = spring({
    frame,
    fps,
    config: { damping: 12, mass: 0.5, stiffness: 100 },
  });
  const titleOpacity = interpolate(frame, [0, 12], [0, 1], { extrapolateRight: "clamp" });
  const titleY = interpolate(titleSpring, [0, 1], [35, 0]);

  const subtextOpacity = interpolate(frame, [15, 28], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const subtextY = interpolate(frame, [15, 28], [15, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Scene exit fade
  const exitFrames = Math.round(0.4 * fps);
  const exitStart = Math.max(0, durFrames - exitFrames);
  const exitOpacity = interpolate(frame, [exitStart, durFrames], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  return (
    <AbsoluteFill
      style={{
        background: "radial-gradient(ellipse at center, rgba(30, 41, 59, 0.9) 0%, #0B1D26 100%)",
        color: "#f8fafc",
        fontFamily: "'Nirmala UI', sans-serif",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        padding: "8%",
        textAlign: "center",
        opacity: exitOpacity,
        overflow: "hidden",
        width: "100%",
        height: "100%",
      }}
    >
      {/* Headline */}
      <div
        style={{
          fontSize: 56,
          fontWeight: 800,
          lineHeight: 1.25,
          letterSpacing: "-0.02em",
          maxWidth: "80%",
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
          textShadow: "0 4px 20px rgba(0, 0, 0, 0.6)",
        }}
      >
        "Both coders and non-coders can build AI agents"
      </div>

      {/* Subtext / Keyword */}
      

      
    </AbsoluteFill>
  );
};

export default Scene2;
